local _, WFJ = ...
WFJ.Data.add("book", {
  ["cb15630e98fe4b45"] = { "⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧\n\nIn molte culture il finire dell'anno su Azeroth è considerato un tempo di cambiamento. I nani e i tauren, in particolare, vedono nella leggenda dell'arrivo del Grande Inverno, il manto di neve che ricopre la terra annunciando un tempo di rinnovamento, un'occasione di festa. Sebbene il modo in cui le razze di Azeroth intendono le leggende che hanno in comune non sia molto diverso, i modi in cui scelgono di celebrarle sono vari quanto le razze stesse.", "." },
  ["cb312d0494f8f8da"] = { "The Bleeding Sparrow: manifesto di carico\n\n(20) barili di rum. Destinazione: Theramore\n(50) sacchi di farina. Destinazione: Theramore\n(2) casse di attrezzi gnomeschi assortiti. Destinazione: ⟦Ratchet=Porto Paranco⟧\n(30) rotoli di stoffa di cotone. Destinazione: Theramore\n(4) casse di spezie. Destinazione: Theramore\n(3) passeggeri. Destinazione: Theramore", "." },
  ["cbad3ba8491e82d3"] = { "Speziale Lydon,\n\nspero che questa lettera ti raggiunga in fretta e che chi la porta sia in buone condizioni. Nella lontana Kalimdor è sorta una necessità che, credo, richiederà le tue capacità.\n\nSarò breve.\n\nSulle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, non lontano da Mulgore, la patria dei nostri alleati tauren, si sta sviluppando una crisi. La S.P.R. & Co., gestita dai goblin, estrae minerali e abbatte alberi senza sosta su quelle montagne, facendo infuriare gli spiriti della montagna.", "." },
  ["cbb8129bb59002db"] = { "Fu in quel periodo che Kil'jaeden scoprì il rigoglioso mondo di Draenor, che fluttuava placido nella Grande Oscurità dell'Oltre. Patria degli orchi, sciamani e divisi in clan, e dei pacifici draenei, Draenor era tanto idilliaco quanto vasto.", "." },
  ["cbbb4210ab398bc4"] = { "Kael, a sua volta mago di grande talento, cominciò a diffidare dell'⟦Alliance=Alleanza⟧ in declino. Gli alti elfi piangevano la perdita della loro patria e decisero di chiamarsi elfi del sangue in onore del loro popolo caduto. Eppure, mentre lottavano per tenere a bada il Flagello, soffrivano molto per essere stati separati dal Pozzo Solare che dava loro forza.", "." },
  ["cbca8a8a95dfceba"] = { "Zanne di Ragno Bruciate:\n\nIl minerale di incendicite che si trova in una grotta nei pressi del ⟦Thelgen Rock=Masso di Thelgen⟧ ha bruciato i ragni che vi dimorano.\n\nIl veleno nelle loro zanne ribolle e reagisce con le zanne stesse, creando una sostanza durissima.", "." },
  ["cbdb3e7b7394aa14"] = { "La bestia che regna su quest'isola è davvero terribilmente potente. Le altre creature qui si fanno piccole davanti a lui, Skyman e Jaguero allo stesso modo. Anche adesso sento i suoi ruggiti, e mi fanno sussultare.\n\nQueste creature fermeranno di certo chiunque venga sull'isola. Devo avere fede nei miei antenati.", "." },
})
